package cn.campus.treehole.web;

import cn.campus.treehole.repo.*;
import cn.campus.treehole.domain.Enums.Role;
import cn.campus.treehole.service.CurrentUserService;
import cn.campus.treehole.security.RefreshTokenService;
import cn.campus.treehole.service.AiModelClient;
import cn.campus.treehole.service.AiEnhancementService;
import cn.campus.treehole.web.ApiErrorHandler.ApiException;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.time.Instant;
import java.util.*;
import static cn.campus.treehole.domain.Enums.*;

@RestController @RequestMapping("/api/v1/admin") @PreAuthorize("hasRole('ADMIN')") @RequiredArgsConstructor
public class AdminController {
  private final IdentityAccessRequestRepository access; private final UserRepository users; private final CurrentUserService current; private final RefreshTokenService refreshTokens; private final AiModelClient aiModel; private final AiEnhancementService aiAnalysis; private final JdbcTemplate jdbc;
  public record AccessView(UUID id,UUID caseId,String teacherName,String reason,AccessStatus status){}
  public record UserView(UUID id,String email,String name,Role role,String status){}
  public record StatusRequest(@jakarta.validation.constraints.NotNull UserStatus status,@jakarta.validation.constraints.NotBlank String reason){}
  public record ReasonRequest(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=1000) String reason){}
  @GetMapping("/users") public List<UserView> users(@RequestParam(required=false) Role role){ return users.findAll().stream().filter(u->role==null||u.getRole()==role).map(u->new UserView(u.getId(),u.getEmail(),u.getDisplayName(),u.getRole(),u.getStatus().name())).toList(); }
  @GetMapping("/identity-requests") @Transactional(readOnly=true) public List<AccessView> requests(){ return access.findAllByOrderByCreatedAtDesc().stream().map(a->new AccessView(a.getId(),a.getRiskCase().getId(),a.getTeacher().getDisplayName(),a.getReason(),a.getStatus())).toList(); }
  @PostMapping("/identity-requests/{id}/{decision}") @Transactional public AccessView decide(@PathVariable UUID id,@PathVariable String decision){if(!Set.of("approve","reject").contains(decision))throw new ApiException(HttpStatus.BAD_REQUEST,"Unsupported decision");var actor=current.get();var a=access.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Request not found"));a.setStatus("approve".equals(decision)?AccessStatus.APPROVED:AccessStatus.REJECTED);a.setReviewedBy(actor);a.setReviewedAt(Instant.now());audit(actor.getId(),"IDENTITY_"+a.getStatus(),"IDENTITY_REQUEST",a.getId(),"");notify(a.getTeacher().getId(),"Identity access "+a.getStatus().name().toLowerCase(),"Your HIGH-risk identity access request was "+a.getStatus().name().toLowerCase()+".");return new AccessView(a.getId(),a.getRiskCase().getId(),a.getTeacher().getDisplayName(),a.getReason(),a.getStatus());}
  @PostMapping("/users/{id}/status") @Transactional public UserView status(@PathVariable UUID id,@jakarta.validation.Valid @RequestBody StatusRequest req){var actor=current.get();var user=users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"User not found"));if(user.getRole()==Role.ADMIN)throw new ApiException(HttpStatus.BAD_REQUEST,"The administrator account cannot be disabled");user.setStatus(req.status());if(req.status()!=UserStatus.ACTIVE)refreshTokens.revokeAll(user.getId());audit(actor.getId(),"USER_STATUS_"+req.status(),"USER",id,req.reason());notify(user.getId(),"Account status updated","Your account status is now "+req.status()+". Reason: "+req.reason());return new UserView(user.getId(),user.getEmail(),user.getDisplayName(),user.getRole(),user.getStatus().name());}
  @PostMapping("/users/{id}/warning") @Transactional public void warn(@PathVariable UUID id,@jakarta.validation.Valid @RequestBody ReasonRequest req){var actor=current.get();var user=users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"User not found"));jdbc.update("insert into user_warnings(user_id,admin_id,reason) values (?,?,?)",id,actor.getId(),req.reason());audit(actor.getId(),"WARN_USER","USER",id,req.reason());notify(id,"Administrator warning",req.reason());}
  @GetMapping("/audit-logs") public List<Map<String,Object>> logs(){ return jdbc.queryForList("select l.id,l.action,l.target_type,l.target_id,l.details,l.created_at,coalesce(u.display_name,'System') actor from audit_logs l left join users u on u.id=l.actor_id order by l.created_at desc limit 500"); }
  @GetMapping("/reports") public List<Map<String,Object>> reports(){ return jdbc.queryForList("select r.id,r.record_id,r.reason,r.details,r.status,r.created_at,e.content from reports r join emotion_records e on e.id=r.record_id order by r.created_at desc"); }
  @PostMapping("/reports/{id}/{decision}") @Transactional public void reportDecision(@PathVariable UUID id,@PathVariable String decision){if(!Set.of("hide","reject").contains(decision))throw new ApiException(HttpStatus.BAD_REQUEST,"Unsupported report decision");var rows=jdbc.queryForList("select record_id from reports where id=?",id); if(rows.isEmpty()) throw new ApiException(HttpStatus.NOT_FOUND,"Report not found"); UUID record=(UUID)rows.getFirst().get("record_id"); if("hide".equals(decision)) jdbc.update("update emotion_records set moderation_status='HIDDEN' where id=?",record); jdbc.update("update reports set status=? where id=?","hide".equals(decision)?"ACCEPTED":"REJECTED",id); jdbc.update("insert into audit_logs(actor_id,action,target_type,target_id,details) values (?,?,?,?,?)",current.get().getId(),"REPORT_"+decision.toUpperCase(),"REPORT",id,""); }
  @GetMapping("/moderation") public List<Map<String,Object>> moderation(){return jdbc.queryForList("select e.id,case when e.visibility='PRIVATE' then null else e.title end title,case when e.visibility='PRIVATE' then null else e.content end content,e.visibility,e.violation_category,e.moderation_status,e.risk_level,e.created_at,u.display_name author,(select count(*) from reports r where r.record_id=e.id and r.status='PENDING') pending_reports from emotion_records e join users u on u.id=e.author_id where e.deleted_at is null and (e.moderation_status in ('PENDING_REVIEW','HIDDEN') or exists(select 1 from reports r where r.record_id=e.id and r.status='PENDING')) order by e.created_at desc");}
  @PostMapping("/moderation/{recordId}/{decision}") @Transactional public void moderate(@PathVariable UUID recordId,@PathVariable String decision){var actor=current.get();String status=switch(decision){case "publish","restore"->"PUBLISHED";case "hide"->"HIDDEN";default->throw new ApiException(HttpStatus.BAD_REQUEST,"Unsupported moderation decision");};var rows=jdbc.queryForList("select author_id from emotion_records where id=?",recordId);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"Record not found");jdbc.update("update emotion_records set moderation_status=? where id=?",status,recordId);UUID author=(UUID)rows.getFirst().get("author_id");jdbc.update("insert into notifications(user_id,title,content,target_path) values (?,?,?,?)",author,"Post review completed",status.equals("PUBLISHED")?"Your post was approved and is now visible in the Treehole community.":"Your post was not published after administrator review.","/records/"+recordId);audit(actor.getId(),"MODERATION_"+decision.toUpperCase(),"EMOTION_RECORD",recordId,"");}
  @PostMapping("/risk-cases/{caseId}/false-positive") @Transactional public void falsePositive(@PathVariable UUID caseId){var actor=current.get();var rows=jdbc.queryForList("select record_id,false_positive from risk_cases where id=? for update",caseId);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"Risk case not found");if(Boolean.TRUE.equals(rows.getFirst().get("false_positive")))throw new ApiException(HttpStatus.CONFLICT,"This case is already marked as a false positive");UUID record=(UUID)rows.getFirst().get("record_id");jdbc.update("update risk_cases set false_positive=true,status='CLOSED',updated_at=now() where id=?",caseId);jdbc.update("update emotion_records set recommendation_eligible=true,moderation_status=case when moderation_status='PENDING_REVIEW' and visibility='PUBLIC' and coalesce(violation_category,'NONE')='NONE' then 'PUBLISHED' else moderation_status end where id=?",record);jdbc.update("insert into risk_case_history(case_id,actor_id,action,to_status,details) values (?,?,?,?,?)",caseId,actor.getId(),"MARK_FALSE_POSITIVE","CLOSED","Risk false positive; independent content review preserved");audit(actor.getId(),"MARK_FALSE_POSITIVE","RISK_CASE",caseId,"");}
  @GetMapping("/ai-tasks") public List<Map<String,Object>> aiTasks(){return jdbc.queryForList("select t.id,t.record_id,t.status,t.attempts,t.last_error,t.created_at,t.updated_at,e.visibility,e.risk_level from ai_analysis_tasks t join emotion_records e on e.id=t.record_id order by t.created_at desc limit 300");}
  @GetMapping("/ai-status") public Map<String,Object> aiStatus(){return Map.of("externalModelConfigured",aiModel.configured(),"privateEntriesLocalOnly",true);}
  @GetMapping("/ai-tasks/{id}/results") public List<Map<String,Object>> aiResults(@PathVariable UUID id){var rows=jdbc.queryForList("select r.source,r.primary_emotion,r.intensity,r.risk_level,r.explicit_plan,r.imminent_timing,r.means_present,r.violation_category,r.confidence,r.support_card,r.reason,r.created_at,e.visibility from ai_analysis_results r join emotion_records e on e.id=r.record_id where r.task_id=? order by r.created_at",id);for(var row:rows){if("PRIVATE".equals(row.get("visibility")))row.put("reason",privateRuleCategories(String.valueOf(row.get("reason"))));row.remove("visibility");}return rows;}
  @PostMapping("/ai-tasks/{id}/reanalyse-local") @Transactional public Map<String,UUID> reanalyseLocal(@PathVariable UUID id){var recordId=jdbc.query("select record_id from ai_analysis_tasks where id=?",rs->rs.next()?(UUID)rs.getObject(1):null,id);if(recordId==null)throw new ApiException(HttpStatus.NOT_FOUND,"AI task not found");UUID newTask=aiAnalysis.reanalyseLocal(recordId);audit(current.get().getId(),"REANALYSE_LOCAL","AI_TASK",newTask,"from task="+id);return Map.of("taskId",newTask);}
  @PostMapping("/ai-tasks/{id}/retry") @Transactional public void retry(@PathVariable UUID id){var rows=jdbc.queryForList("select e.visibility,e.deleted_at from ai_analysis_tasks t join emotion_records e on e.id=t.record_id where t.id=?",id);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"AI task not found");if(!"PUBLIC".equals(rows.getFirst().get("visibility"))||rows.getFirst().get("deleted_at")!=null)throw new ApiException(HttpStatus.CONFLICT,"Private or deleted entries use local analysis only");if(!aiModel.configured())throw new ApiException(HttpStatus.CONFLICT,"External AI is not configured; local analysis remains available");jdbc.update("update ai_analysis_tasks set status='PENDING',attempts=0,last_error='',next_attempt_at=now(),updated_at=now() where id=?",id);audit(current.get().getId(),"RETRY_AI_ANALYSIS","AI_TASK",id,"");}
  private void notify(UUID user,String title,String content){jdbc.update("insert into notifications(user_id,title,content) values (?,?,?)",user,title,content);}
  private void audit(UUID actor,String action,String type,UUID target,String details){jdbc.update("insert into audit_logs(actor_id,action,target_type,target_id,details) values (?,?,?,?,?)",actor,action,type,target,details);}
  private String privateRuleCategories(String reason){var categories=new ArrayList<String>();for(String label:List.of("Self-harm expression","First-person self-harm intent","Explicit plan","Imminent timing","Potential means","Severe hopelessness","Sustained distress","Everyday distress","Content moderation match"))if(reason.contains(label))categories.add(label);return categories.isEmpty()?"Local classification only":String.join("; ",categories);}
}
